{
  "project_id": "36229c61bf4e45ab8773",
  "query": "create schema if not exists private;

-- Memberships are used as the authorization source. Users may inspect only
-- their own memberships; the document policies below can therefore safely
-- consult this table under RLS.
alter table public.memberships enable row level security;
create policy "memberships_select_own"
  on public.memberships for select
  to authenticated
  using ((select auth.uid()) = user_id);

-- Documents are visible only while active. A membership in any role grants
-- read access; write policies distinguish editors and admins.
alter table public.documents enable row level security;

create policy "documents_select_active_member"
  on public.documents for select
  to authenticated
  using (
    deleted_at is null
    and exists (
      select 1
      from public.memberships m
      where m.user_id = (select auth.uid())
        and m.org_id = documents.org_id
    )
  );

create policy "documents_insert_owned_editor_or_admin"
  on public.documents for insert
  to authenticated
  with check (
    owner_id = (select auth.uid())
    and deleted_at is null
    and exists (
      select 1
      from public.memberships m
      where m.user_id = (select auth.uid())
        and m.org_id = documents.org_id
        and m.role in ('editor', 'admin')
    )
  );

create policy "documents_update_owned_or_admin"
  on public.documents for update
  to authenticated
  using (
    deleted_at is null
    and exists (
      select 1
      from public.memberships m
      where m.user_id = (select auth.uid())
        and m.org_id = documents.org_id
        and (
          m.role = 'admin'
          or (m.role = 'editor' and documents.owner_id = (select auth.uid()))
        )
    )
  )
  with check (
    exists (
      select 1
      from public.memberships m
      where m.user_id = (select auth.uid())
        and m.org_id = documents.org_id
        and (
          m.role = 'admin'
          or (m.role = 'editor' and documents.owner_id = (select auth.uid()))
        )
    )
  );

create policy "documents_delete_owned_or_admin"
  on public.documents for delete
  to authenticated
  using (
    deleted_at is null
    and exists (
      select 1
      from public.memberships m
      where m.user_id = (select auth.uid())
        and m.org_id = documents.org_id
        and (
          m.role = 'admin'
          or (m.role = 'editor' and documents.owner_id = (select auth.uid()))
        )
    )
  );

-- Audit rows are written only by the trigger functions, not by API clients.
alter table public.document_audit enable row level security;

create or replace function private.audit_document_change()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, private
as $$
begin
  insert into public.document_audit (document_id, actor_id, action)
  values (
    new.id,
    (select auth.uid()),
    case
      when tg_op = 'INSERT' then 'insert'
      when old.deleted_at is null and new.deleted_at is not null then 'delete'
      else 'update'
    end
  );
  return new;
end;
$$;

create or replace function private.soft_delete_document()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, private
as $$
begin
  update public.documents
     set deleted_at = coalesce(deleted_at, clock_timestamp())
   where id = old.id;
  return null; -- suppress the physical DELETE
end;
$$;

revoke all on function private.audit_document_change() from public, anon, authenticated;
revoke all on function private.soft_delete_document() from public, anon, authenticated;

drop trigger if exists documents_audit_insert_update on public.documents;
create trigger documents_audit_insert_update
after insert or update on public.documents
for each row execute function private.audit_document_change();

drop trigger if exists documents_soft_delete on public.documents;
create trigger documents_soft_delete
before delete on public.documents
for each row execute function private.soft_delete_document();

-- Required API privileges (RLS remains the row-level authorization boundary).
grant select on public.memberships to authenticated;
grant select, insert, update, delete on public.documents to authenticated;

create index if not exists memberships_user_org_idx
  on public.memberships (user_id, org_id);
create index if not exists documents_org_active_idx
  on public.documents (org_id) where deleted_at is null;
"
}

